package org.example.idf_service.web; import jakarta.validation.Valid; import org.example.idf_service.dto.*; import org.example.idf_service.service.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/clients") public class ClientController { private final LimitService limits; private final TransactionService transactions; public ClientController(LimitService l,TransactionService t){limits=l;transactions=t;} @PostMapping("/limits") ResponseEntity<LimitResponse> create(@Valid @RequestBody LimitRequest request){return ResponseEntity.status(HttpStatus.CREATED).body(limits.create(request));} @GetMapping("/{account}/limits") List<LimitResponse> all(@PathVariable String account){return limits.all(account);} @GetMapping("/{account}/transactions/limit-exceeded") List<ExceededTransactionResponse> exceeded(@PathVariable String account){return transactions.exceeded(account);} }
